const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/companies/%7Bcompany_id%7D/custom_field_definitions',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    tool_name: 'SOME_STRING_VALUE',
    includes_configurable_field_sets_count: 'SOME_BOOLEAN_VALUE',
    'filters[with_label]': 'SOME_STRING_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    sort: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/companies/%7Bcompany_id%7D/custom_field_definitions?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&tool_name=SOME_STRING_VALUE&includes_configurable_field_sets_count=SOME_BOOLEAN_VALUE&filters%5Bwith_label%5D=SOME_STRING_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&sort=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
